// Quarantine/error simulation targets marked fixtures only. No AV exclusions,
// restores from quarantine, module constructors, native loads or game access.
using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.ComponentModel;using DynastyCOT.Collection;
class CollectionBackupSecurityChecks {
 static int checks;static string parent;static Catalog catalog;static byte[] extra;
 static void Check(bool value,string label){if(!value)throw new IOException(label);checks++;}
 static byte[] Plugin(string archive){using(var z=new ZipArchive(File.OpenRead(archive),ZipArchiveMode.Read))using(var s=z.Entries.Single(e=>e.FullName=="ExtraSettings.dll").Open())using(var b=new MemoryStream()){s.CopyTo(b);return b.ToArray();}}
 static string Root(string leaf){string root=Path.Combine(parent,leaf);Directory.CreateDirectory(Path.Combine(root,"Plugins/Old"));File.WriteAllText(Path.Combine(root,".cot-fixture"),"isolated");File.WriteAllText(Path.Combine(root,"MMCModManager.exe"),"fixture only");File.WriteAllBytes(Path.Combine(root,"Plugins/ExtraSettings.dll"),extra);File.WriteAllBytes(Path.Combine(root,"Plugins/Old/one.dll"),extra);File.WriteAllBytes(Path.Combine(root,"Plugins/Old/two.dll"),extra);Directory.CreateDirectory(Path.Combine(root,"Plugins/Old/OfflineDynastySettings"));File.WriteAllText(Path.Combine(root,"Plugins/Old/OfflineDynastySettings/DynastyClocks.json"),"original settings");typeof(Ace.DynastyCOT.UserStorage).GetField("current",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).SetValue(null,new Ace.DynastyCOT.UserStore(Path.Combine(parent,leaf+"-Data")));return root;}
 static CollectionInstaller Engine(string root,Action<string,string> copy=null){return new CollectionInstaller(catalog,new Fixture(root,parent),copy);}
 static Plan Plan(CollectionInstaller engine,string root){return engine.Install(root,new Dictionary<string,ModuleRelease>{{"ExtraSettings",catalog.Get("ExtraSettings").Current}},new PreparedModule[0],null,true);}
 static void Original(string root){Check(Paths.HashFile(Path.Combine(root,"Plugins/ExtraSettings.dll"))==Paths.Hash(extra)&&Paths.HashFile(Path.Combine(root,"Plugins/Old/one.dll"))==Paths.Hash(extra)&&Paths.HashFile(Path.Combine(root,"Plugins/Old/two.dll"))==Paths.Hash(extra),"Canonical and duplicate source bytes intact");Check(File.ReadAllText(Path.Combine(root,"Plugins/Old/OfflineDynastySettings/DynastyClocks.json"))=="original settings","Legacy settings unchanged");}
 static void FailureCase(string name,Action<string,string> writer,int code,string stage){string root=Root(name);var engine=Engine(root,writer);var plan=Plan(engine,root);Exception failure=null;try{engine.Execute(plan,new Dictionary<string,string>(),s=>{});}catch(IOException e){failure=e;}Check(failure!=null,"Backup failure stops operation");var backup=engine.Backups(root).Single();Check(backup.Journal.Status=="backup_failed"&&!backup.Restorable,"Incomplete backup visible but not restorable");Check(backup.Journal.FailureCode==code&&backup.Journal.FailureStage==stage,"Native cause and exact stage retained");Check(backup.Journal.Operations.Count==plan.Operations.Count&&backup.Journal.FailureSource!=null&&backup.Journal.FailureBackup!=null,"Complete source map survives failure");Check(failure.Message.Contains(backup.Journal.FailureSource)&&failure.Message.Contains(backup.Journal.FailureBackup),"Error identifies source and backup");if(code==225||code==226){Check(Paths.Explain(failure).Contains("antivirus block")&&!Paths.Explain(failure).Contains("Close MMC"),"Antivirus cause not mislabeled as MMC or permissions");}Original(root);Check(!File.Exists(Ace.DynastyCOT.UserStorage.Current.Resolve("ExtraSettings/DynastyClocks.json")),"No data copy started during backup failure");bool refused=false;try{engine.Restore(root,backup.Directory);}catch(IOException e){refused=e.Message.Contains("cannot be restored");}Check(refused,"Restore of incomplete backup refused without touching programs");Original(root);}
 static int Main(string[] args){try{parent=Path.GetFullPath(args[0]);Directory.CreateDirectory(parent);catalog=Json.Read<Catalog>(args[1]);extra=Plugin(Path.Combine(args[2],catalog.Get("ExtraSettings").Current.ArchiveName));Check(Paths.Hash(extra)==catalog.Get("ExtraSettings").Current.DllSha256,"Fixture uses exact public bytes");
  foreach(int code in new[]{225,226}){string leaf="av-"+code;FailureCase(leaf,(source,dest)=>{var j=Json.Read<Journal>(Path.Combine(Path.GetDirectoryName(dest),"transaction.json"));Check(j.Status=="preparing"&&j.Operations.Any(o=>o.Backup==Path.GetFileName(dest)&&o.Path.Replace('/',Path.DirectorySeparatorChar)==source.Substring(Path.Combine(parent,leaf).Length+1)),"Journal source map persisted before first copy");throw new Win32Exception(code,"simulated security block");},code,"create backup");}
  FailureCase("permission",(s,d)=>{throw new UnauthorizedAccessException("fixture denied");},5,"create backup");
  FailureCase("deleted-copy",(s,d)=>{File.Copy(s,d);File.Delete(d);},0,"verify backup");
  FailureCase("corrupt-copy",(s,d)=>File.WriteAllText(d,"corrupt fixture bytes"),0,"verify backup");
  string earlier=null;FailureCase("late-quarantine",(s,d)=>{File.Copy(s,d);if(earlier==null)earlier=d;else File.Delete(earlier);},0,"recheck completed backups");
  string delayed=Root("after-data-copy");var de=Engine(delayed);var dp=Plan(de,delayed);bool stopped=false;try{de.Execute(dp,new Dictionary<string,string>(),s=>{if(s.StartsWith("Legacy data preserved")){var b=Directory.GetDirectories(Paths.Resolve(delayed,Paths.Backups)).Single();File.Delete(Path.Combine(b,"0000.bak"));}});}catch(IOException e){stopped=e.Message.Contains("verified additive data copies may remain");}Check(stopped,"Backup loss after data copy stops before programs with accurate data status");Original(delayed);Check(File.ReadAllText(Ace.DynastyCOT.UserStorage.Current.Resolve("ExtraSettings/DynastyClocks.json"))=="original settings","Additive verified settings retained");Check(de.Backups(delayed).Single().Journal.Status=="backup_failed","Delayed loss is diagnostic, not a fictitious failed rollback");
  string good=Root("success");var ge=Engine(good);var gp=Plan(ge,good);string before=Paths.HashFile(Path.Combine(good,"Plugins/Old/one.dll"));string saved=ge.Execute(gp,new Dictionary<string,string>(),s=>{});var ready=Json.Read<Journal>(Path.Combine(saved,"transaction.json"));Check(ready.Status=="committed"&&ready.Operations.Where(o=>o.Before!=null).All(o=>o.BackupVerified),"Success requires verified backups");ge.Restore(good,saved);Check(Paths.HashFile(Path.Combine(good,"Plugins/Old/one.dll"))==before,"Verified backup restores exact source");Original(good);
  bool injected=false;try{new CollectionInstaller(catalog,null,(s,d)=>{});}catch(IOException){injected=true;}Check(injected,"Backup injection unavailable outside fixture mode");Check(Paths.WindowsCode(new IOException("generic"))==0,"Generic IO HRESULT not presented as Windows status");Check(Paths.AntivirusCode(new IOException("outer",new Win32Exception(225)))==225,"Nested native antivirus code retained");
  var old=new Journal{Root=good,Status="committed"};Check(new Backup{Journal=old}.Restorable,"Older committed journals retain restore eligibility");var pending=new Journal{Root=good,Status="preparing"};Check(!new Backup{Journal=pending}.Restorable,"Interrupted backup preparation cannot be mistaken for restorable state");Console.WriteLine("PASS "+checks+" backup security/journaling/quarantine/diagnostic/preservation/rollback checks. Fixtures only.");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
